return function(services: IServiceCollection, eventBusProvider: IEventBusProvider)
	local EventChannel = eventBusProvider.GetChannel("ProtocolChannel")

	-- lua protocols
	services:AddSingleton("ILuaProtocols", function(serviceProvider: IServiceProvider)
		local robloxManifest: IRobloxManifest = serviceProvider:GetRequiredService("IRobloxManifest")
		return require(robloxManifest.LuaProtocols)
	end)

	-- lua protocol emiters
	services:AddScoped("IProtocolFacade", function(serviceProvider: IServiceProvider)
		local robloxManifest: IRobloxManifest = serviceProvider:GetRequiredService("IRobloxManifest")
		local protocolEmiter: IProtocolEmiter = serviceProvider:GetRequiredService("IProtocolEmiter")
		return require(robloxManifest.Extensions.IProtocolFacade).new(protocolEmiter)
	end)

	-- 提供 EventChannel 给服务
	local function handler(serviceProvider, moduleScript)
		local Activator: IActivator = serviceProvider:GetRequiredService("IActivator")
		return Activator:CreateInstance(moduleScript, EventChannel)
	end

	services:AddHostedService(function(serviceProvider)
		return handler(serviceProvider, script.Parent.ProtocolReceiver)
	end)

	services:AddHostedService(function(serviceProvider)
		return handler(serviceProvider, script.Parent.ProtocolManager)
	end, "IProtocolManager")

	services:AddPlayerHostedService(function(serviceProvider)
		return handler(serviceProvider, script.Parent.ProtocolEmiter)
	end, "IProtocolEmiter")
end
